class Solution {
public:
    long long numberOfPairs(vector<int>& nums1, vector<int>& nums2, int diff) {
        int n = nums1.size();
        vector<int> a(n);
        for (int i = 0; i < n; i++) a[i] = nums1[i] - nums2[i];
        vector<int> vals;
        vals.reserve(2 * n);
        for (int i = 0; i < n; i++) {
            vals.push_back(a[i]);
            vals.push_back(a[i] + diff);
        }
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int m = vals.size();
        vector<int> bit(m + 2, 0);
        auto update = [&](int i) {
            for (; i <= m; i += i & (-i)) bit[i]++;
        };
        auto query = [&](int i) -> long long {
            long long s = 0;
            for (; i > 0; i -= i & (-i)) s += bit[i];
            return s;
        };
        long long ans = 0;
        for (int j = 0; j < n; j++) {
            int pos = upper_bound(vals.begin(), vals.end(), a[j] + diff) - vals.begin();
            ans += query(pos);
            int p = lower_bound(vals.begin(), vals.end(), a[j]) - vals.begin() + 1;
            update(p);
        }
        return ans;
    }
};
